static int load_float_array(cJSON *arr, float *dst, size_t expected) {
    if (!cJSON_IsArray(arr)) return 0;
    size_t n = (size_t)cJSON_GetArraySize(arr);
    if (n != expected) return 0;
    size_t i = 0;
    cJSON *it = NULL;
    cJSON_ArrayForEach(it, arr) {
        if (!cJSON_IsNumber(it)) return 0;
        dst[i++] = (float)it->valuedouble;
    }
    return 1;
}

/* arr may be a flat array of expected, or nested [[...],[...]] rows each of inner */
static int load_matrix(cJSON *arr, float *dst, size_t rows, size_t inner) {
    if (!cJSON_IsArray(arr)) return 0;
    size_t r = (size_t)cJSON_GetArraySize(arr);
    if (r == rows) {
        /* nested */
        size_t i = 0;
        cJSON *row = NULL;
        cJSON_ArrayForEach(row, arr) {
            if (!load_float_array(row, dst + i * inner, inner)) return 0;
            i++;
        }
        return 1;
    } else if (r == rows * inner) {
        return load_float_array(arr, dst, rows * inner);
    }
    return 0;
}

static int load_weights(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); return 0; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char*)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return 0; }
    if (fread(buf, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(buf); return 0; }
    buf[sz] = 0;
    fclose(f);

    cJSON *root = cJSON_Parse(buf);
    free(buf);
    if (!root) { fprintf(stderr, "JSON parse error\n"); return 0; }

    int ok = load_matrix(cJSON_GetObjectItemCaseSensitive(root, "input_layer.weight"), w_in, HIDDEN, INPUT)
          && load_float_array(cJSON_GetObjectItemCaseSensitive(root, "input_layer.bias"), b_in, HIDDEN)
          && load_matrix(cJSON_GetObjectItemCaseSensitive(root, "hidden_layer.weight"), w_hid, HIDDEN, HIDDEN)
          && load_float_array(cJSON_GetObjectItemCaseSensitive(root, "hidden_layer.bias"), b_hid, HIDDEN)
          && load_matrix(cJSON_GetObjectItemCaseSensitive(root, "output_layer.weight"), w_out, CLASSES, HIDDEN)
          && load_float_array(cJSON_GetObjectItemCaseSensitive(root, "output_layer.bias"), b_out, CLASSES);
    cJSON_Delete(root);
    if (!ok) fprintf(stderr, "weights format error\n");
    return ok;
}

static int recenter(float *px, int n) {
    /* if the image is dark-on-light (mostly bright pixels), flip it */
    double sum = 0.0;
    for (int i = 0; i < n; i++) sum += px[i];
    return (sum / n) < 0.5; /* returns 1 if mostly dark pixels (MNIST-style white-on-black) */
}

